 A^x \cap \{  x\in \ensuremath{D_{\text{fat}}}\} =\{ x \in \ensuremath{D_{\text{fat}}^{c}} \}.
\end{equation}

\begin{equation}\label{A^Tx ineq}
 \ensuremath{\mathbb{P}}(A^{Tx}) \leq \ensuremath{\mathbb{P}}(A^x | C(\mathbf{x}_1) \text{ is retained}).
\end{equation}

\begin{equation}\label{cond eq}
\ensuremath{\mathbb{P}}(A^x)=\ensuremath{\mathbb{P}}(A^x | C(\mathbf{x}_1) \text{ is retained}). 
\end{equation}

